import { crm, loose } from adapters
db = crm()
free = loose()

node Company: "each company named" {
  name: <text> "its name"
}

movement scan(x: <db-[:company]->>) {
  x-[n:notes]-> {
    delete n
  }
  v = "Acme"
  delete v
  people = x-[:people]->
  delete people
  w = IF x.name == "a" THEN x ELSE null END
  delete w
  d = extract from [x.name] {
    node co: "a company" {
      nm: <text> "the name"
    }
  }
  delete d
  d-[k:co]-> {
    delete k
  }
  delete x
}

