import { attio } from adapters
import { acme } from credentials
import { summarise } from plugins
crm = attio(credentials: acme)
function echo(v: <crm-[:company]->>) {
  return v
}
movement m() {
  x1 = acme
  x2 = acme.token
  x3 = "${acme}"
  x4 = acme == "acme"
  if acme == null { ERROR("none") }
  x5 = EXISTS(acme)
  x6 = [acme]
  x7 = { a: acme }
  ERROR("${acme}")
  x8 = AI("say ${acme}")
  x9 = TEXT.PAIRS(acme)
  x10 = AT(acme, "token")
  x11 = echo(acme)
  x12 = summarise(data: acme)
  write crm-[:companies]-> { name: acme }
  return acme
}
movement n(c: <acme-[:company]->>) {
  y = 1
}

